mapper.select:
select tu.name as ownerName, ta.name as activityName, tc.full_name as fullName, tdv.type_value as appellationName, tc.phone as phone, tc.weixin as weixin, tc.qq as qq, tc.email as email, tc.age as age, tc.job as job, tc.year_income as yearIncome, tc.address as address, tdv2.type_value as needLoanName, tp.name as productName, tdv3.type_value as sourceName, tct.description as description, tct.next_contact_time as nextContactTime from t_customer as tct left join t_clue as tc on tct.clue_id = tc.id left join t_user as tu on tc.owner_id = tu.id left join t_activity as ta on tc.activity_id = ta.id left join t_dic_value as tdv on tc.appellation = tdv.id left join t_dic_value as tdv2 on tc.need_loan = tdv2.id left join t_product as tp on tct.product = tp.id left join t_dic_value as tdv3 on tc.source = tdv3.id
tct.id in
#{customerId}
